mapper.select:
SELECT COALESCE(SUM(remaining), 0)
FROM wallet_lot
WHERE user_seq = #{userSeq}
  AND currency_type = #{currencyType}
  AND status = 'ACTIVE'
  AND expire_date >= #{today}

mapper.update:
UPDATE wallet_lot
SET remaining = #{remaining},
    status = #{status}
WHERE lot_seq = #{lotSeq}

UPDATE wallet_lot
SET remaining = remaining + #{amount}
WHERE lot_seq = #{lotSeq}

UPDATE wallet_lot
SET amount = #{amount},
    remaining = #{remaining},
    status = #{status}
WHERE lot_seq = #{lotSeq}
